const b = $json.body || $json || {};
const BRAND = 'Haus of Intelligence, HOI, runs a 14 week AI Architect Simulation cohort. Every Saturday we build one production grade n8n automation live with our operator community and hand over the JSON and the prompts. Audience: Indian founders, operators, and people learning to build and sell AI automation. We are practitioners, not motivational speakers.';
let theme = String(b.theme || b.text || '').trim();
if (!theme) theme = 'How Indian operators make AI automation actually pay for itself';
if (theme.length > 300) theme = theme.slice(0, 300);
const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const start = b.start_iso ? new Date(String(b.start_iso)) : new Date(Date.now() + 86400000);
if (isNaN(start.getTime())) throw new Error('That start date could not be read. Send it as YYYY-MM-DD or leave it out.');
const days = [];
for (let i = 0; i < 7; i++) {
  const d = new Date(start.getTime() + i * 86400000);
  days.push({ day_no: i + 1, day_name: DAYS[(d.getDay() + 6) % 7], post_date: d.toISOString().slice(0, 10), pretty: d.getDate() + ' ' + MONTHS[d.getMonth()] });
}
return [{ json: {
  run_id: 'WEEK-' + Date.now(),
  //chat_id: String(b.chat_id || ''),
  chat_id:'5017296642',
  //email: String(b.email || ''),
  email: 'naikanant381@gmail.com',
  theme: theme,
  week_label: 'Week of ' + days[0].pretty,
  start_iso: days[0].post_date,
  days: days,
  days_text: days.map(x => x.day_no + '. ' + x.day_name + ' ' + x.pretty).join('\n'),
  platform_menu: 'LinkedIn, Instagram, WhatsApp, X, YouTube Shorts',
  format_menu: 'Text post, Carousel, Single image, Story, Broadcast, Short script, Poll',
  brand_context: BRAND
} }];

const cfg = $('1 Read the planning brief').first().json;
const rules = $('2 Load your voice rules').all().map(r => r.json).filter(r => r && r.rule_id);
if (!rules.length) throw new Error('The voice_rules table is empty. The plan would have no voice, so it stops here.');
const style = rules.filter(r => r.rule_type === 'style').map(r => r.rule_id + '. ' + r.rule).join('\n');
const banned = rules.filter(r => r.rule_type === 'banned').map(r => String(r.rule).toLowerCase().trim()).filter(Boolean);
const past = $('3 Load what you already posted').all().map(r => r.json).filter(r => r && (r.angle || r.idea));
const used = past.slice(0, 20).map(r => '- ' + String(r.angle || r.idea)).join('\n') || '- nothing yet, this is the first week';
return [{ json: Object.assign({}, cfg, {
  style_text: style,
  banned: banned,
  banned_text: banned.join(', '),
  already_used: used,
  used_count: past.length,
  rules_count: rules.length
}) }];

const brief = $('4 Build the strategy brief').first().json;
function parse(raw) {
  let t = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s === -1 || e === -1) return null;
  try { return JSON.parse(t.slice(s, e + 1).replace(/,(\s*[}\]])/g, '$1')); } catch (err) { return null; }
}
const c = $json && $json.candidates && $json.candidates[0];
const plan = parse(c && c.content && c.content.parts && c.content.parts[0] && c.content.parts[0].text);
if (!plan || !Array.isArray(plan.slots) || !plan.slots.length) throw new Error('The Strategist did not return a usable plan. That is almost always the Gemini free tier rate limit. Nothing was written to your calendar. Try again in a minute.');
const PLATFORMS = String(brief.platform_menu || '').split(',').map(s => s.trim()).filter(Boolean);
const FORMATS = String(brief.format_menu || '').split(',').map(s => s.trim()).filter(Boolean);
const days = brief.days || [];
const banned = brief.banned || [];
const STOP = {};
'the and for you your that this with from have has are was were will would can could not but they them their our ours when what which who why how all any each more most other some such than then there these those about into over under again once here very just also only own same too make makes made does doing done'.split(' ').forEach(w => { STOP[w] = 1; });
function stem(w) { const sufs = ['ings', 'ing', 'ers', 'er', 'ed', 'es', 's']; for (const s of sufs) { if (w.length - s.length >= 4 && w.slice(-s.length) === s) return w.slice(0, -s.length); } return w; }
function mset(s) { const o = {}; (String(s || '').toLowerCase().match(/[a-z]{4,}/g) || []).forEach(w => { if (!STOP[w]) o[stem(w)] = 1; }); return o; }
function mover(a, b) { const A = mset(a), B = mset(b); const ka = Object.keys(A), kb = Object.keys(B); if (!ka.length || !kb.length) return 0; let h = 0; for (const k of ka) if (B[k]) h++; return h / Math.min(ka.length, kb.length); }
function nums(s) { return (String(s || '').match(/\b\d+(?:[.,]\d+)*\b/g) || []); }
const allowed = nums(String(brief.theme || '') + ' ' + String(brief.brand_context || ''));
const issues = [];
const kept = [];
const usedTopics = [];
const pastText = String(brief.already_used || '');
(plan.slots || []).forEach((s, i) => {
  const tag = 'slot ' + (i + 1) + ': ';
  const dayNo = Number(s.day_no);
  const topic = String(s.topic || '').trim();
  const platform = String(s.platform || '').trim();
  const format = String(s.format || '').trim();
  if (!(dayNo >= 1 && dayNo <= 7)) { issues.push(tag + 'day ' + s.day_no + ' is outside the week, dropped'); return; }
  if (PLATFORMS.indexOf(platform) === -1) { issues.push(tag + 'platform ' + platform + ' is not on your menu, dropped'); return; }
  if (FORMATS.indexOf(format) === -1) { issues.push(tag + 'format ' + format + ' is not on your menu, dropped'); return; }
  if (topic.length < 25) { issues.push(tag + 'the topic is a category, not a claim, dropped'); return; }
  const bad = nums(topic + ' ' + String(s.angle_hint || '')).filter(n => allowed.indexOf(n) === -1);
  if (bad.length) { issues.push(tag + 'invented number ' + bad.slice(0, 2).join(', ') + ', dropped'); return; }
  const low = (topic + ' ' + String(s.angle_hint || '')).toLowerCase();
  const hitBan = banned.filter(b => b && low.indexOf(b) !== -1);
  if (hitBan.length) { issues.push(tag + 'banned phrase ' + hitBan[0] + ', dropped'); return; }
  let dupe = -1;
  for (let j = 0; j < usedTopics.length; j++) { if (mover(topic, usedTopics[j]) > 0.5) { dupe = j; break; } }
  if (dupe !== -1) { issues.push(tag + 'makes the same argument as slot ' + (dupe + 1) + ', dropped'); return; }
  if (mover(topic, pastText) > 0.6) { issues.push(tag + 'repeats something you already posted, dropped'); return; }
  usedTopics.push(topic);
  const d = days[dayNo - 1] || { day_name: 'Day ' + dayNo, post_date: brief.start_iso, pretty: '' };
  kept.push({
    slot_id: brief.run_id + '-' + (kept.length + 1),
    day_no: dayNo,
    day_name: d.day_name,
    post_date: d.post_date,
    pretty: d.pretty,
    platform: platform,
    format: format,
    topic: topic,
    angle_hint: String(s.angle_hint || '').trim(),
    pillar: String(s.pillar || 'General').trim(),
    why_here: String(s.why_here || '').trim()
  });
});
if (!kept.length) throw new Error('Every slot the Strategist proposed failed the checks, so nothing was written to your calendar. Run it again.');
kept.sort((a, b) => a.day_no - b.day_no);
const byDay = {};
kept.forEach(s => { byDay[s.day_no] = byDay[s.day_no] || []; byDay[s.day_no].push(s); });
const missingDays = [];
for (let i = 1; i <= 7; i++) if (!byDay[i]) missingDays.push((days[i - 1] || {}).day_name || ('day ' + i));
if (missingDays.length) issues.push('No slot planned for: ' + missingDays.join(', '));
const counts = {};
kept.forEach(s => { counts[s.platform] = (counts[s.platform] || 0) + 1; });
const mix = Object.keys(counts).map(p => p + ' ' + counts[p]).join(', ');
PLATFORMS.forEach(p => { if (!counts[p]) issues.push(p + ' got no slot this week'); });
Object.keys(counts).forEach(p => { if (counts[p] / kept.length > 0.4) issues.push(p + ' takes ' + Math.round(counts[p] / kept.length * 100) + ' percent of the week, that is too much of one platform'); });
const doubleDays = Object.keys(byDay).filter(k => byDay[k].length > 1).length;
const singleDays = Object.keys(byDay).filter(k => byDay[k].length === 1).length;
if (!doubleDays) issues.push('Every day carries exactly one platform, so nothing is combined');
if (!singleDays) issues.push('Every day carries several platforms, so nothing is alternated');
let score = 100;
score -= Math.min(40, issues.length * 7);
score = Math.max(0, score);
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = ['CONTENT CALENDAR', '', brief.week_label, 'Theme: ' + String(plan.week_theme || brief.theme), '', 'The arc: ' + String(plan.arc || 'not given'), 'Pillars: ' + (Array.isArray(plan.pillars) ? plan.pillars.join(', ') : 'not given'), '', 'PLAN SCORE: ' + score + ' of 100', kept.length + ' slots across ' + Object.keys(byDay).length + ' days. Mix: ' + mix, singleDays + ' single platform days, ' + doubleDays + ' combined days.', ''];
for (let i = 1; i <= 7; i++) {
  const d = days[i - 1] || {};
  const slots = byDay[i] || [];
  lines.push((d.day_name || ('Day ' + i)) + ' ' + (d.pretty || ''));
  if (!slots.length) { lines.push('   nothing planned'); } else {
    slots.forEach(s => { lines.push('   ' + s.platform + ' / ' + s.format + ' [' + s.pillar + ']'); lines.push('   ' + s.topic); });
  }
  lines.push('');
}
if (issues.length) { lines.push('WHAT THE CHECK FLAGGED'); issues.slice(0, 8).forEach(x => lines.push('- ' + x)); lines.push(''); }
lines.push('Send the word build followed by a slot number to produce that one, for example: build 3');
const calendar_text = lines.join('\n').slice(0, 3900);
const CREAM = '#F4F5F0', INK = '#111111', LIME = '#C8F135', FOREST = '#1B7E42', MUTED = '#6B6B6B';
const chip = (t, bg) => '<span style="display:inline-block;background:' + bg + ';color:#111;font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;padding:4px 10px;border-radius:999px;margin-right:6px">' + esc(t) + '</span>';
let rows = '';
for (let i = 1; i <= 7; i++) {
  const d = days[i - 1] || {};
  const slots = byDay[i] || [];
  rows += '<tr><td style="padding:0 28px 14px"><table width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #E4E5DF;border-radius:14px">' +
    '<tr><td style="padding:14px 20px 10px;border-bottom:1px solid #F0F1EC"><b style="font-size:15px;color:' + INK + '">' + esc(d.day_name || ('Day ' + i)) + '</b> <span style="color:' + MUTED + ';font-size:13px">' + esc(d.pretty || '') + '</span>' + (slots.length > 1 ? '<span style="float:right;color:' + FOREST + ';font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase">' + slots.length + ' platforms</span>' : '') + '</td></tr>';
  if (!slots.length) { rows += '<tr><td style="padding:14px 20px;color:' + MUTED + ';font-size:14px">Nothing planned. A rest day.</td></tr>'; }
  slots.forEach(s => {
    rows += '<tr><td style="padding:14px 20px;border-bottom:1px solid #F7F8F4">' + chip(s.platform, LIME) + chip(s.format, '#E8E9E3') + chip(s.pillar, '#E8E9E3') +
      '<div style="margin-top:10px;font-size:15px;line-height:1.55;color:#1a1a1a">' + esc(s.topic) + '</div>' +
      (s.angle_hint ? '<div style="margin-top:6px;font-size:13px;color:' + MUTED + ';line-height:1.55">Entry point: ' + esc(s.angle_hint) + '</div>' : '') +
      (s.why_here ? '<div style="margin-top:4px;font-size:12px;color:' + MUTED + ';line-height:1.55">Why here: ' + esc(s.why_here) + '</div>' : '') +
      '<div style="margin-top:8px;font-size:11px;color:#9A9A9A">' + esc(s.slot_id) + '</div></td></tr>';
  });
  rows += '</table></td></tr>';
}
const stat = (n, l) => '<td align="center" style="padding:0 6px"><div style="font-size:26px;font-weight:700;color:' + INK + ';line-height:1.1">' + esc(n) + '</div><div style="font-size:10px;color:' + MUTED + ';letter-spacing:.06em;text-transform:uppercase;margin-top:5px">' + esc(l) + '</div></td>';
const calendar_html = '<!doctype html><html><body style="margin:0;padding:0;background:' + CREAM + '"><table width="100%" cellpadding="0" cellspacing="0" style="background:' + CREAM + ';font-family:Helvetica,Arial,sans-serif"><tr><td align="center" style="padding:28px 12px"><table width="660" cellpadding="0" cellspacing="0" style="max-width:660px;border:1px solid #E4E5DF;border-radius:18px;overflow:hidden">' +
'<tr><td style="background:' + INK + ';padding:26px 28px"><div style="color:' + LIME + ';font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase">Haus of Intelligence</div><div style="color:#ffffff;font-size:25px;font-weight:700;margin-top:8px">Content Calendar</div><div style="color:#9A9A9A;font-size:13px;margin-top:8px">' + esc(brief.week_label) + '</div></td></tr>' +
'<tr><td style="padding:22px 28px 6px"><div style="font-size:11px;color:' + MUTED + ';letter-spacing:.09em;text-transform:uppercase">The arc of the week</div><div style="font-size:17px;color:' + INK + ';margin-top:8px;line-height:1.5">' + esc(plan.arc || plan.week_theme || brief.theme) + '</div></td></tr>' +
'<tr><td style="padding:16px 28px 20px"><table width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #E4E5DF;border-radius:14px"><tr><td style="padding:18px 10px"><table width="100%"><tr>' + stat(score + '/100', 'Plan score') + stat(kept.length, 'Slots') + stat(Object.keys(counts).length, 'Platforms') + stat(doubleDays, 'Combined days') + '</tr></table></td></tr></table></td></tr>' +
rows +
(issues.length ? '<tr><td style="padding:4px 28px 22px"><table width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px dashed #D5D6D0;border-radius:14px"><tr><td style="padding:16px 20px;font-size:13px;color:#444;line-height:1.7"><b style="color:' + INK + '">What the check flagged</b><br>' + issues.slice(0, 8).map(x => esc(x)).join('<br>') + '</td></tr></table></td></tr>' : '') +
'<tr><td style="background:' + INK + ';padding:20px 28px;text-align:center"><div style="color:' + LIME + ';font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase">Build. Automate. Scale.</div><div style="color:#8A8A8A;font-size:11px;margin-top:7px">Planned by your Content Engine Desk. Nothing has been produced or posted yet.</div></td></tr>' +
'</table></td></tr></table></body></html>';
return [{ json: {
  run_id: brief.run_id, chat_id: brief.chat_id, email: brief.email,
  week_label: brief.week_label, week_theme: String(plan.week_theme || brief.theme), arc: String(plan.arc || ''),
  pillars: Array.isArray(plan.pillars) ? plan.pillars : [],
  slots: kept, slot_count: kept.length, plan_score: score, platform_mix: mix,
  single_days: singleDays, combined_days: doubleDays,
  issues: issues, calendar_text: calendar_text, calendar_html: calendar_html
} }];
